public ContentResult Greet(string name)
{
    return Content("<p>Hello " + System.Net.WebUtility.HtmlEncode(name) + "</p>", "text/html");
}

response.test_code:
[Fact]
public void Greet_encodes_markup_in_the_name()
{
    var html = new GreetingController().Greet("<script>alert(1)</script>").Content!;
    Assert.DoesNotContain("<script>", html);
    Assert.Contains("&lt;script&gt;", html);
}
